                if (maxUnderscore < index - lastPos - 1) {
                    maxUnderscore = index - lastPos - 1;
                }
            }
            if (ch == ')') {
                inParentheses = false;
                if (index - lastPos > 1) {
                    countWords++;
                }
            }
            if (ch == '_' || ch == '(' || ch == ')') {
                lastPos = index;
            }
        }
        if (maxUnderscore < len - lastPos - 1) {
            maxUnderscore = len - lastPos - 1;
        }
        System.out.println(maxUnderscore + " " + countWords);
    }
}
